"use client";

import { ArrowRight, Minus, Plus, X } from "lucide-react";
import { products, photo, money } from "@/data/maison-products";
import { useCommerceStore } from "@/lib/commerce-store";

export function CartDrawer() {
  const drawer = useCommerceStore((state) => state.drawer);
  const cart = useCommerceStore((state) => state.cart);
  const changeCart = useCommerceStore((state) => state.changeCart);
  const setDrawer = useCommerceStore((state) => state.setDrawer);
  const cartItems = products.filter((product) => cart[product.id]);
  const cartCount = Object.values(cart).reduce((sum, count) => sum + count, 0);
  const total = cartItems.reduce((sum, product) => sum + product.price * cart[product.id], 0);

  if (drawer !== "cart") return null;

  return (
    <div className="overlay" onClick={() => setDrawer(null)}>
      <aside className="drawer" onClick={(event) => event.stopPropagation()} aria-label="Votre panier">
        <div className="drawer-head"><span>Votre panier</span><button onClick={() => setDrawer(null)} aria-label="Fermer"><X size={20} /></button></div>
        {cartItems.length === 0 ? <div className="empty-drawer"><p>Votre panier attend sa première pièce.</p><a href="/products" onClick={() => setDrawer(null)}>Découvrir les collections ↗</a></div> : <div className="drawer-items">{cartItems.map((product) => <div className="drawer-item" key={product.id}>
          <img src={photo(product.image, 220)} alt="" />
          <div><h3>{product.name}</h3><p>{money(product.price)}</p><div className="quantity"><button onClick={() => changeCart(product.id, -1)} aria-label="Retirer un article"><Minus size={13} /></button><span>{cart[product.id]}</span><button onClick={() => changeCart(product.id, 1)} aria-label="Ajouter un article"><Plus size={13} /></button></div></div>
        </div>)}</div>}
        {cartCount > 0 && <div className="drawer-total"><div><span>Sous-total</span><strong>{money(total)}</strong></div><button onClick={() => setDrawer(null)}>Continuer mes achats <ArrowRight size={16} /></button><small>Livraison calculée à l’étape suivante.</small></div>}
      </aside>
    </div>
  );
}
